{
    "hero": {
        "title": "Advancing Liver Research Through Data",
        "subtitle": "The CFDE Liver Resource is a comprehensive hub for liver research, offering anatomical maps, cellular atlases, disease databases, and integrated data analysis tools."
    },
    "sections": [
        {
            "title": "Highlights",
            "subtitle": "Selected pages available on this resource now",
            "cards": [
                {
                    "title": "Canonical cell types in the healthy human liver",
                    "body": "Explore the cell types which constitute the human liver.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/celltype8.png",
                    "link": "/cell-type-atlas"
                },{
                    "title": "Liver single cell map",
                    "body": "Integrated single cell liver map with data from >100 human donors from HuBMAP, SenNet, and more.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/cellmap.png",
                    "link": "/single-cell-map.html"
                },{
                    "title": "Gene expression",
                    "body": "Curated cell states and computationally inferred gene programs for liver with genetically supported links to human traits.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/heatmap.png",
                    "link": "/gene-expression.html"
                },{
                    "title": "Explore liver datasets",
                    "body": "Common Fund projects host multiomic, multilevel data pertaining to the liver. Use the query engine here to discover liver-associated data within CFDE DCCs.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/liverwheel2.png",
                    "link": "/datasets"
                }
            ]
        },
        {
            "title": "Information",
            "subtitle": "Learn about liver anatomy, cells, and diseases",
            "cards": [
                {
                    "title": "Liver anatomy",
                    "body": "Explore annotated liver anatomy highlighting spatial organization and regions.",
                    "image": "",
                    "link": "#"
                },{
                    "title": "Canonical cell types in the healthy human liver",
                    "body": "Explore the cell types which constitute the human liver.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/celltype8.png",
                    "link": "/cell-type-atlas"
                },{
                    "title": "Liver functional tissue units",
                    "body": "Explore functional tissue units in the liver defined by HuBMAP.",
                    "image": "",
                    "link": "https://dev.cfdeliverresource.org/functional-atlas.html"
                },{
                    "title": "Liver diseases",
                    "body": "Explore the diseases of the liver and their etiologies, with a focus on predicting understudied genes for each disease.",
                    "image": "",
                    "link": "#"
                }
            ]
        },
        {
            "title": "Data & Tools",
            "subtitle": "Find datasets and workflows, learn about our data model and standards",
            "cards": [
                {
                    "title": "Explore liver datasets",
                    "body": "Common Fund projects host multiomic, multilevel data pertaining to the liver. Use the query engine here to discover liver-associated data within CFDE DCCs.",
                    "image": "https://hugeampkpncms.org/sites/default/files/images/cfde/cfde_liverportal/liverwheel2.png",
                    "link": "/datasets"
                },{
                    "title": "Tools and workflows",
                    "body": "Identify and use tools and workflows for interactively or remotely analyzing data from CFDE and/or publicly available resources.",
                    "image": "",
                    "link": "#"
                },{
                    "title": "Query, analysis, and visualization",
                    "body": "An interactive browser to query CFDE and other liver data resources, interfaces to perform integrative data analysis, and visualization interfaces post-analysis.",
                    "image": "",
                    "link": "#"
                }
            ]
        },
        {
            "title": "Community",
            "subtitle": "Learn how to use this resource, connect with the community, and find help",
            "cards": [
                {
                    "title": "Use cases",
                    "body": "Provides examples of integrated data analysis leading to biological insights.",
                    "image": "",
                    "link": "https://bdcw.org/LiverPortal/liver_atlas_use_case_MASLD.html"
                },{
                    "title": "Hypothesis engine",
                    "body": "Generate new hypotheses from the Liver Workbench for further exploration and validation.",
                    "image": "",
                    "link": "#"
                },{
                    "title": "Wiki",
                    "body": "Contribute new hypotheses and knowledge from your analysis using the liver Wiki.",
                    "image": "",
                    "link": "#"
                },{
                    "title": "Publications",
                    "body": "Explore links to extant liver-related literature along with annotations.",
                    "image": "",
                    "link": "#"
                }
            ]
        }
    ],
    "support":{
        "title": "Supported By",
        "subtitle":"The NIH Common Fund Data Ecosystem",
        "images": [
            {
                "src": "https://cdn.jsdelivr.net/gh/broadinstitute/site-shell@main/public/assets/drc_portrait.png",
                "link": "https://info.cfde.cloud"
            },
            {
                "src": "https://cdn.jsdelivr.net/gh/broadinstitute/site-shell@main/public/assets/cfde_kc_logo_c.png",
                "link": "https://cfdeknowledge.org"
            }
        ]
    }
}
